import os
os.makedirs("system", exist_ok=True)
block = """FoamFile { version 2.0; format ascii; class dictionary; object blockMeshDict; }
convertToMeters 1;
vertices
(
 (-0.028 -0.028 -0.008)
 ( 0.028 -0.028 -0.008)
 ( 0.028  0.028 -0.008)
 (-0.028  0.028 -0.008)
 (-0.028 -0.028  0.008)
 ( 0.028 -0.028  0.008)
 ( 0.028  0.028  0.008)
 (-0.028  0.028  0.008)
);
blocks ( hex (0 1 2 3 4 5 6 7) (12 12 6) simpleGrading (1 1 1) );
edges ();
boundary ( );
"""
# cell size: 0.056/12 ~= 0.0047 -> coarse
open("system/blockMeshDict","w").write(block)
subprocess.run(["blockMesh"], check=True)
print("blockMesh ok")

