    spinner_wetted.stl { type triSurfaceMesh; name spinner_wetted; }
    endGapTop.stl { type triSurfaceMesh; name endGapTop; }
    endGapBottom.stl { type triSurfaceMesh; name endGapBottom; }
}
castellatedMeshControls
