    x0,y0,z0,x1,y1,z1 = gmsh.model.getBoundingBox(dim, tag)
    rmax = max(abs(x0),abs(x1))
    zc = (z0+z1)/2
    if rmax > 1e-4:  # cylinder
        r = round(rmax, 5)
        if abs(r-0.0230) < 1e-4: groups_map["ring_wetted"].append(tag)
