for dim,tag in gmsh.model.getEntities(2):
    x0,y0,z0,x1,y1,z1 = gmsh.model.getBoundingBox(dim, tag)
    dz = z1-z0
    r = max(abs(x0),abs(x1))
    zc=(z0+z1)/2
    if dz > 1e-4:  # cylinder
        name = "ring_wetted" if abs(r-0.023)<1e-4 else "spinner_wetted"
    else:
